-- VetMate | 06_clinic.sql | Chay sau 05_seed_medical_catalog.sql
-- PostgreSQL camelCase: luon dung dau ngoac kep cho ten bang/cot.
-- Bang duoc tao KHONG kem du lieu mau. Chay tren DB dev/test da backup.
BEGIN;
CREATE SCHEMA IF NOT EXISTS clinic;

CREATE TABLE IF NOT EXISTS clinic."clinicStaff" (
 "staffID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "userID" BIGINT NOT NULL UNIQUE REFERENCES auth."users"("userID") ON DELETE RESTRICT,
 "staffCode" VARCHAR(30) NOT NULL UNIQUE,
 "staffType" VARCHAR(30) NOT NULL CHECK ("staffType" IN ('CLINIC_MANAGER','RECEPTIONIST','VETERINARIAN','LAB_TECHNICIAN','ASSISTANT','OTHER')),
 "hireDate" DATE,
 "status" VARCHAR(20) NOT NULL DEFAULT 'ACTIVE' CHECK ("status" IN ('ACTIVE','INACTIVE')),
 "note" TEXT,
 "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
 "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS clinic."veterinarians" (
 "veterinarianID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "staffID" BIGINT NOT NULL UNIQUE REFERENCES clinic."clinicStaff"("staffID") ON DELETE RESTRICT,
 "licenseNumber" VARCHAR(100), "bio" TEXT, "yearsExperience" INTEGER CHECK ("yearsExperience" IS NULL OR "yearsExperience" >= 0),
 "consultationNote" TEXT, "status" VARCHAR(20) NOT NULL DEFAULT 'ACTIVE' CHECK ("status" IN ('ACTIVE','INACTIVE'))
);
CREATE TABLE IF NOT EXISTS clinic."specialties" (
 "specialtyID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "name" VARCHAR(150) NOT NULL UNIQUE, "description" TEXT, "isActive" BOOLEAN NOT NULL DEFAULT true
);
CREATE TABLE IF NOT EXISTS clinic."veterinarianSpecialties" (
 "veterinarianID" BIGINT NOT NULL REFERENCES clinic."veterinarians"("veterinarianID") ON DELETE CASCADE,
 "specialtyID" BIGINT NOT NULL REFERENCES clinic."specialties"("specialtyID") ON DELETE RESTRICT,
 "isPrimary" BOOLEAN NOT NULL DEFAULT false,
 PRIMARY KEY ("veterinarianID", "specialtyID")
);
CREATE UNIQUE INDEX IF NOT EXISTS "uqVetPrimarySpecialty" ON clinic."veterinarianSpecialties" ("veterinarianID") WHERE "isPrimary" = true;

CREATE TABLE IF NOT EXISTS clinic."serviceCategories" (
 "categoryID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "name" VARCHAR(150) NOT NULL UNIQUE, "description" TEXT, "isActive" BOOLEAN NOT NULL DEFAULT true
);
CREATE TABLE IF NOT EXISTS clinic."services" (
 "serviceID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "categoryID" BIGINT NOT NULL REFERENCES clinic."serviceCategories"("categoryID") ON DELETE RESTRICT,
 "serviceCode" VARCHAR(30) NOT NULL UNIQUE, "name" VARCHAR(200) NOT NULL,
 "description" TEXT, "price" NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK ("price" >= 0),
 "defaultDurationMinutes" INTEGER NOT NULL DEFAULT 30 CHECK ("defaultDurationMinutes" > 0 AND "defaultDurationMinutes" % 15 = 0),
 "requiresVeterinarian" BOOLEAN NOT NULL DEFAULT true,
 "isBookable" BOOLEAN NOT NULL DEFAULT true,
 "isEmergency" BOOLEAN NOT NULL DEFAULT false,
 "status" VARCHAR(20) NOT NULL DEFAULT 'ACTIVE' CHECK ("status" IN ('ACTIVE','INACTIVE')),
 "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
 CONSTRAINT "ckEmergencyNotBookable" CHECK (NOT "isEmergency" OR NOT "isBookable")
);
CREATE TABLE IF NOT EXISTS clinic."serviceSpecialties" (
 "serviceID" BIGINT NOT NULL REFERENCES clinic."services"("serviceID") ON DELETE CASCADE,
 "specialtyID" BIGINT NOT NULL REFERENCES clinic."specialties"("specialtyID") ON DELETE RESTRICT,
 PRIMARY KEY ("serviceID", "specialtyID")
);
CREATE TABLE IF NOT EXISTS clinic."veterinarianServices" (
 "veterinarianID" BIGINT NOT NULL REFERENCES clinic."veterinarians"("veterinarianID") ON DELETE CASCADE,
 "serviceID" BIGINT NOT NULL REFERENCES clinic."services"("serviceID") ON DELETE RESTRICT,
 "customDurationMinutes" INTEGER CHECK ("customDurationMinutes" IS NULL OR ("customDurationMinutes" > 0 AND "customDurationMinutes" % 15 = 0)),
 "isActive" BOOLEAN NOT NULL DEFAULT true, "note" TEXT,
 PRIMARY KEY ("veterinarianID", "serviceID")
);

-- Ca lam nguyen ngay: 07:30-11:30, 13:00-17:00; luu theo NGAY, khong tach ca.
CREATE TABLE IF NOT EXISTS clinic."workingSchedules" (
 "scheduleID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "veterinarianID" BIGINT NOT NULL REFERENCES clinic."veterinarians"("veterinarianID") ON DELETE RESTRICT,
 "workDate" DATE NOT NULL,
 "morningStartTime" TIME NOT NULL DEFAULT '07:30', "morningEndTime" TIME NOT NULL DEFAULT '11:30',
 "afternoonStartTime" TIME NOT NULL DEFAULT '13:00', "afternoonEndTime" TIME NOT NULL DEFAULT '17:00',
 "status" VARCHAR(20) NOT NULL DEFAULT 'AVAILABLE' CHECK ("status" IN ('AVAILABLE','UNAVAILABLE')),
 "isEmergencyLead" BOOLEAN NOT NULL DEFAULT false,
 "assignedByStaffID" BIGINT REFERENCES clinic."clinicStaff"("staffID") ON DELETE SET NULL,
 "note" TEXT, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
 CONSTRAINT "uqVetWorkDate" UNIQUE ("veterinarianID", "workDate"),
 CONSTRAINT "ckWorkDayTimes" CHECK ("morningStartTime" < "morningEndTime" AND "morningEndTime" <= "afternoonStartTime" AND "afternoonStartTime" < "afternoonEndTime"),
 CONSTRAINT "ckEmergencyLeadAvailable" CHECK (NOT "isEmergencyLead" OR "status" = 'AVAILABLE')
);
CREATE UNIQUE INDEX IF NOT EXISTS "uqEmergencyLeadPerDay" ON clinic."workingSchedules" ("workDate") WHERE "isEmergencyLead" AND "status"='AVAILABLE';
CREATE INDEX IF NOT EXISTS "idxWorkSchedulesDateStatus" ON clinic."workingSchedules" ("workDate", "status");

CREATE TABLE IF NOT EXISTS clinic."staffLeaves" (
 "leaveID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "staffID" BIGINT NOT NULL REFERENCES clinic."clinicStaff"("staffID") ON DELETE RESTRICT,
 "startAt" TIMESTAMPTZ NOT NULL, "endAt" TIMESTAMPTZ NOT NULL,
 "reason" TEXT NOT NULL,
 "status" VARCHAR(25) NOT NULL DEFAULT 'PENDING' CHECK ("status" IN ('PENDING','APPROVED','REJECTED','CANCELLED')),
 "reviewedByStaffID" BIGINT REFERENCES clinic."clinicStaff"("staffID") ON DELETE SET NULL,
 "reviewedAt" TIMESTAMPTZ, "reviewNote" TEXT,
 "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
 CONSTRAINT "ckStaffLeaveRange" CHECK ("endAt" > "startAt")
);
CREATE INDEX IF NOT EXISTS "idxStaffLeavesStaffStatus" ON clinic."staffLeaves" ("staffID", "status", "startAt");

CREATE OR REPLACE FUNCTION clinic."touchUpdatedAt"() RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN NEW."updatedAt" = now(); RETURN NEW; END; $$;
DO $$ DECLARE t TEXT; BEGIN
 FOREACH t IN ARRAY ARRAY['clinicStaff','services','workingSchedules','staffLeaves'] LOOP
  EXECUTE format('DROP TRIGGER IF EXISTS "trgTouchUpdatedAt" ON clinic.%I', t);
  EXECUTE format('CREATE TRIGGER "trgTouchUpdatedAt" BEFORE UPDATE ON clinic.%I FOR EACH ROW EXECUTE FUNCTION clinic."touchUpdatedAt"()', t);
 END LOOP;
END $$;
COMMIT;
